package com.example.spring_blog.util;import com.example.spring_blog.error.Exception400;import com.example.spring_blog.error.Exception500;import lombok.extern.slf4j.Slf4j;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.Paths;import java.util.Map;import java.util.UUID;// FileUtil은 상태도 없고, 다른 빈에 의존하지않는 순수한 도구함수.// static 메서드 활용@Slf4jpublic class FileUtil {    //    업로드 폴더 : 사용자 홈 폴더 아래 blog_uploads (운영채제 관계없이 동작함)    public static final String UPLOAD_DIR = Paths.get(System.getProperty("user.home"), "blog_uploads").toString();//                                                              ㄴ os사용자의 홈경로 폴더 조회    //    허용하는 이미지 형식과 저장할 확장자 설정    private static final Map<String, String> IMAGE_TYPES = Map.of(            "image/jpeg", ".jpg",            "image/png", ".png",            "image/gif", ".gif",            "image/webp", ".webp"    );//    이미지 저장 : 저장할 파일 이름을 반환 (없으면 null)    public static String saveImage(MultipartFile file) {//        파일저장은 선택사항        if (file == null || file.isEmpty()) {            return null;        }//        허용한 이미지 형식인지 확인        if (!isImageFile(file)) {            throw new Exception400("이미지 파일은 JPG, PNG, GIF, WEBP 형식만 가능합니다.");        }        String extension = IMAGE_TYPES.get(file.getContentType());        String saveFilename = UUID.randomUUID() + extension;        Path uploadPath = Paths.get(UPLOAD_DIR);        try {            Files.createDirectories(uploadPath);            file.transferTo(uploadPath.resolve(saveFilename));        }catch (IOException e) {            log.error("파일 저장 실패 :  {} ", e.getMessage());            throw new Exception500("파일 저장 중 오류가 발생했습니다");        }        return saveFilename;    }    public static void deleteFile(String filename) {        if (filename == null || filename.isBlank()) {            return;        }        try {            Files.deleteIfExists(Paths.get(UPLOAD_DIR, filename));        } catch (IOException e) {            log.warn("파일 삭제 실패 : {}", e.getMessage());        }    }//    편의 메서드 : 허용한 이미지 형식인지 확인    public static boolean isImageFile(MultipartFile file) {        if (file == null || file.getContentType() == null) {            return false; //형식정보가 없으면 허용하지 않음.        }        return IMAGE_TYPES.containsKey(file.getContentType());    }}